-- ============================================================================
-- Jeu de données de test — Plateforme d'accès aux aires protégées FANAMBY
-- ============================================================================
-- Base cible : projet_stage (MySQL / MariaDB), après « php artisan migrate ».
-- Le script VIDE les tables de l'application puis les remplit : il peut être
-- relancé à tout moment pour revenir à cet état de départ. Toutes les tables
-- portent le préfixe t_. Les modèles de la page Références (t_modeles_reference)
-- ne sont pas touchés : ils sont créés par la migration et gérés par les admins.
--
-- Les dates sont relatives au jour d'exécution (CURDATE(), NOW()) : retards,
-- arrivées imminentes et séjours en cours restent cohérents quel que soit le jour.
--
-- Comptes (mot de passe pour tous : password)
--   admin@fanamby.org        admin
--   validateur@fanamby.org   validateur (Andrafiamena, Anjozorobe, Loky)
--   alice@exemple.com        demandeur
--   hery@fanamby.org         validateur (Anjozorobe, Menabe)
--   rado@exemple.com, sarah@exemple.com, tiana@exemple.com   demandeurs
--   « Allée des Baobabs » n'a volontairement aucun validateur.
--
-- Pièces jointes : les lignes de t_documents pointent vers storage/app/private/demandes/{id}/.
-- Sans ces fichiers, le téléchargement d'une pièce affiche « Fichier introuvable ».
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE t_notifications;
TRUNCATE TABLE t_documents_officiels;
TRUNCATE TABLE t_documents_reference;
TRUNCATE TABLE t_historique_statuts;
TRUNCATE TABLE t_documents;
TRUNCATE TABLE t_demandes;
TRUNCATE TABLE t_periode_sensibles;
TRUNCATE TABLE t_site_user;
TRUNCATE TABLE t_regles_specifiques;
TRUNCATE TABLE t_documents_requis;
TRUNCATE TABLE t_type_demandes;
TRUNCATE TABLE t_sites;
TRUNCATE TABLE t_statuts;
TRUNCATE TABLE t_sessions;
TRUNCATE TABLE t_password_reset_tokens;
TRUNCATE TABLE t_users;
-- Cache de l'application (dont la liste des sites de la page d'accueil, voir Site::pourAccueil)
TRUNCATE TABLE t_cache;
SET FOREIGN_KEY_CHECKS = 1;

